 const auto value=parse_footprints_workbench_footprint_json(raw);assert(!value.dfg_present&&value.dfg.size()==2&&value.dfg.at({"Z","A"})==0);assert(value.sequence.size()==2&&value.start_activities.size()==2);assert(value.activities==std::set<std::string>{"contradictory"});assert(value.skippable&&!*value.skippable&&value.activities_always_happening&&value.activities_always_happening->empty());assert(value.min_trace_length==std::numeric_limits<std::size_t>::max()&&!value.min_trace_length_present&&value.max_trace_length_without_loops==0&&value.trace->size()==4);
 const auto encoded=serialize_footprints_workbench_json(value);assert(serialize_footprints_workbench_json(parse_footprints_workbench_footprint_json(encoded))==encoded);contains(encoded,R"("dfg_present":false)");contains(encoded,R"("min_trace_length":18446744073709551615,"min_trace_length_present":false)");
 const auto empty=parse_footprints_workbench_footprint_json("{}");assert(empty.dfg_present&&empty.start_activities_present&&empty.end_activities_present&&empty.min_trace_length_present&&!empty.trace&&!empty.activities_always_happening&&!empty.skippable);
 const auto engaged=parse_footprints_workbench_footprint_json(R"({"trace":[],"activities_always_happening":[],"min_trace_length":0})");assert(engaged.trace&&engaged.trace->empty()&&engaged.activities_always_happening&&engaged.min_trace_length==0);
 const auto vector=parse_footprints_workbench_footprints_json("["+std::string(raw)+",{},"+std::string(raw)+"]");assert(vector.size()==3&&serialize_footprints_workbench_json(vector[0])==serialize_footprints_workbench_json(vector[2]));
