 for(const auto* input:{"null",R"({"unknown":0})",R"({"dfg":null})",R"({"dfg":[{"source":"A","target":"B","count":0},{"source":"A","target":"B","count":1}]})",R"({"dfg":[{"source":"A","target":"B","count":18446744073709551616}]})",R"({"min_trace_length":-0})",R"({"min_trace_length":1.0})",R"({"sequence":[{"source":"A"}]})",R"({"trace":[null]})",R"({"dfg_present":true,"dfg_present":false})"})rejects([&]{(void)parse_footprints_workbench_footprint_json(input);});
