void both_tree_decoration_surfaces_keep_sparse_native_preorder(){
 ProcessTree tree({"A","B","A"},ProcessTreeNode{ProcessTreeOperator::kSequence,0,{ProcessTreeNode::leaf(0),ProcessTreeNode::leaf(1),ProcessTreeNode::leaf(2)}});const auto before=serialize_process_tree_alignment_input_json(tree);
 const auto sets=parse_footprints_workbench_decoration_json(R"({"relations":[{"source":"A","target":"B"}],"start_activities":["A","missing","A"],"end_activities":["B"],"activities_always_happening":["A"]})");assert(sets.start_activities.size()==2);const auto decorations=fc::TreeVisualizationProjection::decorate(tree,sets.relations,sets.start_activities,sets.end_activities,sets.activities_always_happening);assert(decorations.size()==2&&decorations[0].preorder_index==2&&decorations[0].activity=="B"&&decorations[1].preorder_index==3&&decorations[1].activity=="A"&&decorations[1].color=="blue");const auto encoded=serialize_footprints_workbench_json(decorations);contains(encoded,R"("operation_index":0)");
 FootprintsExtensiveResult result;result.footprints=sets.relations;result.start_activities=sets.start_activities;result.end_activities=sets.end_activities;result.activities_always_happening=sets.activities_always_happening;assert(serialize_footprints_workbench_json(fc::TreeVisualizationProjection::decorate(tree,result))==encoded);assert(fc::TreeVisualizationProjection::decorate(tree,sets.relations,{}, {},sets.activities_always_happening).empty());assert(serialize_process_tree_alignment_input_json(tree)==before);
}
